// ===================================
// Document Statistics Aggregator
// Returns counts by category, department, type, etc.
// ===================================

const response = $input.item.json;

if (!response || !response.facet_counts) {
  return {
    json: {
      success: false,
      error: "No facet data available from API",
      total_documents: 0,
      statistics: {}
    }
  };
}

const facetCounts = response.facet_counts;
const results = response.results || [];

// Extract categories from document IDs/names (BMS-DEPT-CAT-NNN format)
const categories = {
  "PRO": 0,    // Process
  "FOR": 0,    // Form
  "GUI": 0,    // Guide/Guidance
  "POL": 0,    // Policy
  "TEM": 0,    // Template
  "other": 0
};

// Count by category from document IDs
for (const result of results) {
  const docId = result.document_id || result.document_name || "";

  // Match BMS-DEPT-CAT-NNN pattern
  const match = docId.match(/BMS-[A-Z]{2,4}-([A-Z]{3})-\d+/);

  if (match) {
    const cat = match[1]; // PRO, FOR, GUI, etc.
    if (categories.hasOwnProperty(cat)) {
      categories[cat]++;
    } else {
      categories.other++;
    }
  } else {
    categories.other++;
  }
}

// Map category codes to friendly names
const categoryNames = {
  "PRO": "Process",
  "FOR": "Form",
  "GUI": "Guide",
  "POL": "Policy",
  "TEM": "Template",
  "other": "Other/Uncategorized"
};

const categoryStats = {};
for (const [code, count] of Object.entries(categories)) {
  if (count > 0) {
    categoryStats[categoryNames[code] || code] = count;
  }
}

// Get department counts
const departments = facetCounts.department || {};
const departmentStats = Object.entries(departments)
  .filter(([dept]) => dept !== "unknown" && dept !== "")
  .sort((a, b) => b[1] - a[1])
  .reduce((acc, [dept, count]) => {
    acc[dept] = count;
    return acc;
  }, {});

// Get file type counts
const fileTypes = facetCounts.document_type || {};
const fileTypeStats = Object.entries(fileTypes)
  .sort((a, b) => b[1] - a[1])
  .reduce((acc, [type, count]) => {
    acc[type.toUpperCase()] = count;
    return acc;
  }, {});

// Get standards compliance counts
const standards = facetCounts.standard_compliance || {};
const standardStats = Object.entries(standards)
  .filter(([std]) => std !== "unknown" && std !== "")
  .map(([std, count]) => {
    // Parse comma-separated standards
    const stdList = std.split(',').map(s => s.trim()).filter(s => s);
    return { standards: stdList, count: count };
  })
  .filter(item => item.standards.length > 0);

// Count individual standards
const individualStandards = {};
for (const item of standardStats) {
  for (const std of item.standards) {
    individualStandards[std] = (individualStandards[std] || 0) + item.count;
  }
}

// Sort individual standards
const sortedStandards = Object.entries(individualStandards)
  .sort((a, b) => b[1] - a[1])
  .reduce((acc, [std, count]) => {
    acc[std] = count;
    return acc;
  }, {});

// Calculate totals
const totalDocuments = response.total_results || 0;
const totalByCategory = Object.values(categories).reduce((sum, val) => sum + val, 0);
const totalByDepartment = Object.values(departmentStats).reduce((sum, val) => sum + val, 0);
const totalByFileType = Object.values(fileTypeStats).reduce((sum, val) => sum + val, 0);

// Build summary text
let summary = `📊 **BMS Document Statistics**\n\n`;
summary += `**Total Documents:** ${totalDocuments}\n\n`;

if (Object.keys(categoryStats).length > 0) {
  summary += `**By Document Category:**\n`;
  for (const [cat, count] of Object.entries(categoryStats)) {
    const percentage = totalByCategory > 0 ? ((count / totalByCategory) * 100).toFixed(1) : "0.0";
    summary += `• ${cat}: ${count} (${percentage}%)\n`;
  }
  summary += "\n";
}

if (Object.keys(fileTypeStats).length > 0) {
  summary += `**By File Type:**\n`;
  for (const [type, count] of Object.entries(fileTypeStats)) {
    const percentage = totalByFileType > 0 ? ((count / totalByFileType) * 100).toFixed(1) : "0.0";
    summary += `• ${type}: ${count} (${percentage}%)\n`;
  }
  summary += "\n";
}

if (Object.keys(departmentStats).length > 0) {
  summary += `**By Department (Top 10):**\n`;
  const topDepts = Object.entries(departmentStats).slice(0, 10);
  for (const [dept, count] of topDepts) {
    const percentage = totalByDepartment > 0 ? ((count / totalByDepartment) * 100).toFixed(1) : "0.0";
    summary += `• ${dept}: ${count} (${percentage}%)\n`;
  }

  if (Object.keys(departmentStats).length > 10) {
    summary += `• ...and ${Object.keys(departmentStats).length - 10} more departments\n`;
  }
  summary += "\n";
}

if (Object.keys(sortedStandards).length > 0) {
  summary += `**By ISO/EN Standards (Top 8):**\n`;
  const topStds = Object.entries(sortedStandards).slice(0, 8);
  for (const [std, count] of topStds) {
    summary += `• ${std}: ${count} documents\n`;
  }
  if (Object.keys(sortedStandards).length > 8) {
    summary += `• ...and ${Object.keys(sortedStandards).length - 8} more standards\n`;
  }
}

// Build structured response
const result = {
  success: true,
  total_documents: totalDocuments,

  statistics: {
    by_category: categoryStats,
    by_file_type: fileTypeStats,
    by_department: departmentStats,
    by_standard: sortedStandards
  },

  summary: summary,

  metadata: {
    query_time: new Date().toISOString(),
    source: "Qdrant vector database",
    collection: "nomad_bms_documents",
    results_analyzed: results.length
  }
};

return { json: result };
